package com.vibeguard.samples.refunds; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Positive; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Limits refund operations to callers holding the internal staff key. */ @RestController @RequestMapping("/internal/refunds") public class RefundController { private final Map<String,Refund> refunds=new ConcurrentHashMap<>(); @Value("${INTERNAL_STAFF_KEY:}") private String staffKey; @PostMapping public ResponseEntity<Refund> create(@RequestHeader("X-Internal-Key") String key,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();String id=UUID.randomUUID().toString();Refund refund=new Refund(id,request.paymentId(),request.amount(),"PENDING");refunds.put(id,refund);return ResponseEntity.status(201).body(refund);}@GetMapping("/{id}") public ResponseEntity<Refund> get(@RequestHeader("X-Internal-Key") String key,@PathVariable String id){if(!allowed(key))return ResponseEntity.status(401).build();Refund refund=refunds.get(id);return refund==null?ResponseEntity.notFound().build():ResponseEntity.ok(refund);}private boolean allowed(String key){return !staffKey.isBlank()&&staffKey.equals(key);}record Request(@NotBlank String paymentId,@Positive long amount){}record Refund(String id,String paymentId,long amount,String status){} }
